html:
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:.1f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro person(employee) -%}{{ v(frappe.db.get_value("Employee", employee, "employee_name") if employee else "") }}{%- endmacro -%}
<style>
.lpl-form { font-family: Cambria, Georgia, serif; font-size: 11.5px; color: #000; line-height: 1.45; }
.lpl-form p { margin: 0 0 8px; }
.lpl-form table { width: 100%; border-collapse: collapse; margin: 0 0 12px; }
.lpl-form tr { page-break-inside: avoid; }
.lpl-form th, .lpl-form td { border: 1px solid #000; padding: 4px 6px; vertical-align: top; text-align: left; }
.lpl-form th { background: #f2f2f2; font-weight: bold; }
.lpl-form h3 { font-size: 12.5px; text-align: center; text-transform: uppercase; margin: 8px 0 12px; }
.lpl-form h4 { font-size: 11.5px; font-weight: bold; margin: 12px 0 6px; }
.lpl-form .rule { min-height: 34px; white-space: pre-wrap; border: 1px solid #000; padding: 4px 6px; margin: 0 0 12px; }
.lpl-form .scores td, .lpl-form .scores th { text-align: center; }
.lpl-form .scores td { font-weight: bold; }
.lpl-form .right { text-align: right; }
.lpl-form .muted { color: #444; font-size: 10.5px; }
.lpl-form table.bare { border: none; }
.lpl-form table.bare > tbody > tr > td, .lpl-form table.bare > tr > td { border: none; padding: 0; }
.lpl-form .pre { white-space: pre-wrap; }
.lpl-form .nowrap { white-space: nowrap; }
.lpl-form .grid td, .lpl-form .grid th { text-align: center; vertical-align: middle; height: 30px; }
.lpl-form .grid td { width: 27%; font-size: 10.5px; }
.lpl-form .grid .axis { width: 19%; font-weight: bold; background: #f2f2f2; }
.lpl-form .grid .here { background: #bfbfbf; font-weight: bold; font-size: 11.5px; }
.lpl-form .sign td { border: none; padding: 14px 6px 0 0; width: 33%; }
.lpl-form .sign .line { border-top: 1px solid #000; padding-top: 3px; }
</style>
{%- macro money(value) -%}{{ "{:,.0f}".format(value | float) if value else "" }}{%- endmacro -%}
<div class="lpl-form">
<h3>Individual Development Plan</h3>
<table>
<tr><th style="width:18%">Employee</th><td>{{ v(doc.employee_name) }}</td>
<th style="width:17%">Designation</th><td>{{ v(doc.designation) }}</td></tr>
<tr><th>Department</th><td>{{ v(doc.department) }}</td><th>Plant</th><td>{{ v(doc.branch) }}</td></tr>
<tr><th>Programme</th><td>{{ v(doc.program_type) }}</td><th>Mentor or Coach</th><td>{{ person(doc.mentor) }}</td></tr>
<tr><th>Period</th><td>{{ day(doc.start_date) }} to {{ day(doc.end_date) }}</td><th>Status</th><td>{{ v(doc.status) }}</td></tr>
{%- if doc.succession_position %}
<tr><th>Grown for the Role</th>
<td>{{ v(frappe.db.get_value("Succession Position", doc.succession_position, "designation")) }}</td>
<th>Succession Plan</th><td>{{ v(doc.succession_position) }}</td></tr>
{%- endif %}
{%- if doc.box_name and doc.has_permlevel_access_to("box_name") %}
<tr><th>Nine-Box Placement</th><td>{{ v(doc.box_name) }}</td><th>From Placement</th><td>{{ v(doc.placement) }}</td></tr>
{%- endif %}
</table>

<h4>Objectives</h4>
<div class="rule">{{ v(doc.objectives) }}</div>

<h4>Development Actions</h4>
{%- set ns = namespace(done=0, cost=0.0) %}
<table>
<tr><th style="width:4%">#</th><th>Development Action</th><th style="width:11%">Duration</th><th style="width:11%">By When</th>
<th style="width:16%">By Whom</th><th style="width:11%">Est. Cost</th><th style="width:12%">Completed On</th></tr>
{%- for row in doc.actions %}
{%- if row.completed_on %}{% set ns.done = ns.done + 1 %}{% endif %}
{%- set ns.cost = ns.cost + (row.estimated_cost or 0) %}
<tr><td>{{ loop.index }}</td><td class="pre">{{ v(row.action) }}</td><td>{{ v(row.duration) }}</td><td class="nowrap">{{ day(row.by_when) }}</td>
<td>{{ v(row.by_whom) }}</td><td class="right">{{ money(row.estimated_cost) }}</td><td class="nowrap">{{ day(row.completed_on) }}</td></tr>
{%- endfor %}
<tr><th colspan="5" class="right">Estimated Cost</th><td class="right"><b>{{ money(ns.cost) }}</b></td><td></td></tr>
</table>
<p>{{ ns.done }} of {{ doc.actions | length }} actions done.
{%- if doc.training_requisition %} The training is requested from L&amp;D on {{ v(doc.training_requisition) }}.{% endif %}</p>

{%- if doc.score_after or doc.decision or doc.outcome_notes %}
<h4>Review</h4>
<table class="scores">
<tr><th>Score Before</th><th>Score After</th><th>Movement</th><th>Effectiveness</th><th>Decision</th></tr>
<tr><td>{{ num(doc.score_before) }}</td><td>{{ num(doc.score_after) }}</td>
<td>{{ "{:+.1f}".format(doc.movement | float) if doc.score_after else "" }}</td>
<td>{{ v(doc.effectiveness) }}</td><td>{{ v(doc.decision) }}</td></tr>
</table>
<div class="rule">{{ v(doc.outcome_notes) }}</div>
{%- endif %}

<h4>Agreement</h4>
<p>We agree to this plan, to the support set out in it, and to review it when it ends.</p>
<table class="sign"><tr>
<td><div class="line">Employee: {{ v(doc.employee_name) }}</div><span class="muted">Sign and date</span></td>
<td><div class="line">Mentor or Coach: {{ person(doc.mentor) }}</div><span class="muted">Sign and date</span></td>
<td><div class="line">Human Resources: {{ who(doc.enrolled_by) }}</div><span class="muted">Date {{ day(doc.enrolled_on) }}</span></td>
</tr></table>
{%- if doc.reviewed_by %}
<p class="muted">Reviewed by {{ who(doc.reviewed_by) }} on {{ day(doc.reviewed_on) }}.</p>
{%- endif %}
</div>
